    await expect(page.getByText(/400 Broad St/).first().or(page.getByRole('textbox', { name: /^Address/ }))).toBeVisible();

    // В Clients — два разных клиента с этим номером: «+972537240114» и QA-John Miller (старый, от 02.11)
    await page.goto('/customers');
